head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 바인딩된 DataList 의 CheckBoxDisabled 항목(disabled 컬럼) 값과 화면 CheckBox 의 disabled 상태를 함께 출력
scwin.printState = function (strPrefix) {
    var objDlt = $p.getComponentById("dlt_item");
    scwin.setReturnValue(strPrefix + " CheckBoxDisabled 항목값 : " + objDlt.getColData("disabled"));

    var arrInput = document.querySelectorAll('input[id*="target1_checkbox"]');
    var arrState = [];
    for (var i = 0; i < arrInput.length; i++) {
        arrState.push(arrInput[i].disabled);
    }
    scwin.setReturnValue(strPrefix + " 화면 CheckBox disabled : " + arrState.join(","));
};

// 항목1 (value=1) 의 CheckBox 를 활성 상태로 변경
scwin.btn_enable_onclick = function (e) {
    $p.getComponentById("target1").disableCheckboxByValue("1", false);
    scwin.printState("[항목1 활성화]");
};

// 항목2 (value=2) 의 CheckBox 를 비활성 상태로 변경
scwin.btn_disable_onclick = function (e) {
    $p.getComponentById("target1").disableCheckboxByValue("2", true);
    scwin.printState("[항목2 비활성화]");
};
